'use strict';
// STAGED ONLY. Pure adapters: persistence and provider submission are deliberately injected elsewhere.
const check=(v,m)=>{if(!v)throw Error(m)};
const copy=x=>JSON.parse(JSON.stringify(x));
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function readLocked(row,owner){
 check(row?.id===1&&row.owner===String(owner),'Shared lock not owned');
 const s=typeof row.reviewLedger==='string'?JSON.parse(row.reviewLedger):copy(row.reviewLedger);
 const r=typeof row.managedClips==='string'?JSON.parse(row.managedClips):copy(row.managedClips);
 check(s?.schemaVersion===1&&Number.isSafeInteger(s.generation)&&s.clips&&s.receipts,'Invalid ledger');
 check(r?.schemaVersion===1&&Array.isArray(r.clipIds)&&new Set(r.clipIds).size===r.clipIds.length,'Invalid registry');
 return {s,r};
}
function approvedClip(row,owner,id){
 const {s,r}=readLocked(row,owner),c=s.clips[id];
 check(r.clipIds.includes(id)&&c?.mode==='current-render-v1','Current-render managed review required');
 check(c.status==='Approved'&&!c.pendingRefresh&&c.final?.reviewGeneration&&c.approval?.reviewGeneration===c.final.reviewGeneration,'Current clip approval required');
 check(c.approval.projectId===c.projectId&&c.approval.clipId===c.final.clipId&&c.approval.actor,'Approval identity mismatch');
 return {s,r,c};
}
function approveCurrent({row,owner,recordId,expectedVersion,reviewGeneration,persistedAuthor,verifiedOwner}){
 const {s,r}=readLocked(row,owner),c=s.clips[recordId];
 check(persistedAuthor?.id===verifiedOwner?.id&&persistedAuthor?.email===verifiedOwner?.email&&verifiedOwner?.id,'Owner-authored persisted intent required');
 check(r.clipIds.includes(recordId)&&c?.mode==='current-render-v1'&&!c.pendingRefresh,'Current-render preview required');
 check(c.version===expectedVersion&&c.status==='Needs Review'&&c.final?.reviewGeneration===reviewGeneration&&reviewGeneration,'Displayed preview stale');
 check(c.final.renderReady===true&&c.final.transcript?.trim()&&/^https:\/\//.test(c.final.url),'Ready media and transcript required');
 check(!Object.values(s.receipts).some(x=>x.recordId===recordId&&x.state!=='completed'),'Unresolved review receipt');
 const next=copy(s);next.generation++;next.clips[recordId]={...c,version:c.version+1,status:'Approved',approval:{projectId:c.projectId,clipId:c.final.clipId,reviewGeneration,actor:persistedAuthor.id}};
 return {expectedGeneration:s.generation,reviewLedger:JSON.stringify(next)};
}
function draftSource({row,owner,recordId,parentId}){
 const {c}=approvedClip(row,owner,recordId);check(c.parentId===parentId,'Parent mismatch');
 return {recordId,parentId,projectId:c.projectId,clipId:c.final.clipId,url:c.final.url,transcript:c.final.transcript,reviewGeneration:c.final.reviewGeneration};
}
function draftBinding({source,post}){
 check(post.parentId===source.parentId&&post.clipRecordId===source.recordId,'Draft linkage mismatch');
 check(['Instagram','YouTube'].includes(post.platform)&&post.body?.trim(),'Invalid clip draft');
 return {...post,reviewGeneration:source.reviewGeneration,approved:false,publishingStatus:'Draft'};
}
function prepareSchedule({row,owner,post,provider,accounts,now}){
 const {s,c}=approvedClip(row,owner,post.clipRecordId);
 check(post.parentId===c.parentId,'Post parent mismatch');
 const key='schedule|'+post.id,old=s.receipts[key];
 if(old){check(old.postId===post.id,'Receipt mismatch');return {action:old.state==='confirmed'?'already-scheduled':'reconcile',receipt:old};}
 check(post.approved===true&&post.publishingStatus==='Draft'&&!post.externalPostId,'Post not eligible');
 check(post.reviewGeneration===c.final.reviewGeneration,'Draft review stale');
 check(provider.id===c.projectId+'.'+c.final.clipId&&provider.renderAsVideoFile?.pending===false,'Provider identity/render mismatch');
 check(['Instagram','YouTube'].includes(post.platform),'Unsupported automatic platform');
 check(['Alex Woung','Alex Woung Raw'].includes(post.channel),'Unknown content channel');
 check(Number.isFinite(Date.parse(post.publishAt))&&Date.parse(post.publishAt)>now,'Future time required');
 const account=accounts.find(a=>a.id===post.accountId&&a.platform===post.platform&&a.channel===post.channel);
 check(account,'Exact connected destination required');
 check(post.platform!=='Instagram'||account.subAccountId,'Instagram subaccount required');
 const body={projectId:c.projectId,clipId:c.final.clipId,postAccountId:account.id,...(account.subAccountId?{subAccountId:account.subAccountId}:{}),postDetail:{title:post.title||'',custom:{description:post.body,privacy:'public'},mediaType:'video'},publishAt:new Date(post.publishAt).toISOString()};
 return {action:'persist-intent-first',key,expectedGeneration:s.generation,postId:post.id,recordId:c.id,reviewGeneration:c.final.reviewGeneration,body};
}
function persistScheduleIntent({row,owner,prepared}){
 const {s}=readLocked(row,owner);check(prepared.action==='persist-intent-first'&&s.generation===prepared.expectedGeneration&&!s.receipts[prepared.key],'Concurrent schedule intent');
 const n=copy(s);n.generation++;n.receipts[prepared.key]={state:'pending',postId:prepared.postId,recordId:prepared.recordId,reviewGeneration:prepared.reviewGeneration,body:prepared.body};
 return {expectedGeneration:s.generation,reviewLedger:JSON.stringify(n)};
}
function verifyScheduleIntent({row,owner,prepared}){
 const {s}=readLocked(row,owner),r=s.receipts[prepared.key];check(r?.state==='pending'&&r.postId===prepared.postId&&same(r.body,prepared.body),'Durable intent readback required');return prepared.body;
}
function providerOutcome({row,owner,key,response}){
 const {s}=readLocked(row,owner),r=s.receipts[key];check(r?.state==='pending','Pending receipt required');
 const rawId=response?.data?.scheduleId??response?.scheduleId;
 const id=typeof rawId==='string'&&rawId.trim()?rawId.trim():null;
 const n=copy(s);n.generation++;n.receipts[key]={...r,state:typeof id==='string'&&id.trim()?'confirmed':'uncertain',...(typeof id==='string'&&id.trim()?{scheduleId:id}:{})};
 // Failure/timeout never resets to Draft. Reconcile the provider before any retry.
 return {expectedGeneration:s.generation,reviewLedger:JSON.stringify(n),fields:id?{'Publishing Status':'Scheduled','External Post ID':id}:{'Publishing Status':'Publishing','Last Error':'Provider result uncertain. Reconcile before retry.'}};
}

'use strict';
// Pure plans only. Caller owns shared lock, authoritative parent read, durable CAS/readback.
function canonicalSources({row,owner,parent,recordIds}) {
 check(parent?.id&&['Alex Woung','Alex Woung Raw'].includes(parent.fields?.['Content Channel']),'Unknown parent channel');
 const linked=parent.fields['Content Clips'];
 check(Array.isArray(linked)&&Array.isArray(recordIds)&&recordIds.length&&new Set(recordIds).size===recordIds.length,'Invalid clip selection');
 return recordIds.map(recordId=>{check(linked.includes(recordId),'Unlinked clip');return {...draftSource({row,owner,recordId,parentId:parent.id}),channel:parent.fields['Content Channel']};});
}
function bindCreatedDrafts({row,owner,parent,sources,records}) {
 const {s}=readLocked(row,owner); const n=JSON.parse(JSON.stringify(s));n.drafts??={};
 check(Array.isArray(records)&&records.length,'No created drafts');const seen=new Set();
 for(const post of records){
  check(/^rec[A-Za-z0-9]+$/.test(post.id)&&!seen.has(post.id),'Invalid/duplicate post');seen.add(post.id);
  const f=post.fields||{},ids=f['Content Clip'],parents=f['Parent Content'];
  check(Array.isArray(ids)&&ids.length===1&&Array.isArray(parents)&&parents.length===1&&parents[0]===parent.id,'Draft linkage mismatch');
  const source=sources.find(x=>x.recordId===ids[0]);check(source,'Missing generation source');
  const [current]=canonicalSources({row,owner,parent,recordIds:ids});
  check(current.reviewGeneration===source.reviewGeneration&&current.clipId===source.clipId&&current.projectId===source.projectId,'Source changed during generation');
  check(['Instagram','YouTube'].includes(f.Platform)&&f['Content Channel']===current.channel,'Wrong draft destination');
  check(f['Approval Status']==='Needs Review'&&f['Publishing Status']==='Draft'&&!f['External Post ID']&&!f['Scheduled At'],'Created draft is not review-only');
  check(f['Media URL']===current.url&&typeof f['Draft Body']==='string'&&f['Draft Body'].trim(),'Wrong media or empty copy');
  check(!Object.values(s.receipts).some(r=>r.postId===post.id),'Post already has schedule receipt');
  const binding={reviewGeneration:current.reviewGeneration,content:JSON.stringify({clipRecordId:ids[0],parentId:parent.id,platform:f.Platform,channel:current.channel,title:f['Draft Title']||'',body:f['Draft Body']})};
  check(!n.drafts[post.id]||JSON.stringify(n.drafts[post.id])===JSON.stringify(binding),'Existing binding differs; explicit regeneration required');
  n.drafts[post.id]=binding;
 }
 n.generation++;
 return {expectedGeneration:s.generation,reviewLedger:JSON.stringify(n)};
}
const parent=$('Get Parent Content').first().json;
const f=parent.fields??{};
const linkedClipIds=new Set(Array.isArray(f['Content Clips'])?f['Content Clips']:[]);
const clipResponse=$('Get Approved Clips').first().json;
if(clipResponse.offset)throw new Error('Approved clip lookup is paginated; reconcile before generating.');
if((clipResponse.records??[]).some(r=>!linkedClipIds.has(r.id)||r.fields?.['Clip Status']!=='Approved'))throw new Error('Clip lookup returned an unapproved or unrelated clip.');
const contentChannel=String(f['Content Channel']?.name??f['Content Channel']??'').trim();
if(!['Alex Woung','Alex Woung Raw'].includes(contentChannel)) throw new Error('Choose Alex Woung or Alex Woung Raw in the Content Channel field before generating the distribution pack.');

const requestedChannels=(Array.isArray(f['Distribution Channels'])?f['Distribution Channels']:[])
  .map(v=>String(v?.name??v).trim())
  .filter(Boolean);
if(!requestedChannels.length) throw new Error('Choose at least one Distribution Channel before generating the distribution pack.');

const requestedCount=Math.max(1,Math.min(50,Math.round(Number(f['Requested Clip Count']??3))));
const minimumScore=Math.max(0,Math.min(100,Math.round(Number(f['Minimum Clip Score']??85))));

const rawClips=($('Get Approved Clips').first().json.records??[]).map(r=>({
  recordId:r.id,
  clipId:String(r.fields?.['OpusClip Clip ID']??r.id),
  name:String(r.fields?.['Clip Name']??''),
  url:String(r.fields?.['Frame.io Clip URL']??''),
  hook:String(r.fields?.Hook??''),
  caption:String(r.fields?.Caption??''),
  transcript:String(r.fields?.['Clip Transcript']??''),
  score:Number(r.fields?.['Virality Score']??0),
}));
const locked=$('Acquire Distribution Source Lock').first().json;
const {r:registry}=readLocked(locked,$execution.id);
const managedSources=rawClips.filter(x=>registry.clipIds.includes(x.recordId));
const verifiedSources=managedSources.length?canonicalSources({row:locked,owner:$execution.id,parent,recordIds:managedSources.map(x=>x.recordId)}):[];
for(const clip of rawClips){const source=verifiedSources.find(x=>x.recordId===clip.recordId);if(source){clip.clipId=source.projectId+'.'+source.clipId;clip.url=source.url;clip.transcript=source.transcript;clip.reviewGeneration=source.reviewGeneration;}}
const uniqueByClipId=new Map();
for(const clip of rawClips){
  const existing=uniqueByClipId.get(clip.clipId);
  if(!existing || (!existing.transcript && clip.transcript)) uniqueByClipId.set(clip.clipId,clip);
}
const clips=[...uniqueByClipId.values()]
  .filter(c=>c.score>=minimumScore)
  .sort((a,b)=>b.score-a.score)
  .slice(0,requestedCount);

if(!clips.length)throw new Error('Approve at least one qualifying clip before generating this distribution pack.');
if(clips.some(c=>!c.transcript.trim()||!/^https?:\/\//i.test(c.url)))throw new Error('Every selected clip needs its actual transcript and valid media URL before generating.');
const youtubeUrl=String(f['YouTube URL']??'').trim();
const videoUrl=youtubeUrl||String(f['Frame.io Final Asset URL']??'').trim()||String(f.Link??'').trim()||String(f['Frame.io Final Folder URL']??'').trim()||String(f['Frame.io Raw Folder URL']??'').trim();
const transcript=String(f['YouTube Transcript']??'').trim();
if(!transcript)throw new Error('The actual parent video transcript is required before generating distribution drafts.');
const script=String(f.Script??'').trim();
const description=String(f.Description??'').trim();
if(!transcript&&!script&&!description&&!clips.length) throw new Error('No usable source text is available for the selected outputs.');

const specs=[];
if(requestedChannels.includes('Instagram')) specs.push({channel:'Instagram',platform:'Instagram',outputType:'Reel',scope:'one per selected clip'});
if(requestedChannels.includes('YouTube Shorts')) specs.push({channel:'YouTube Shorts',platform:'YouTube',outputType:'Short',scope:'one per selected clip'});
if(requestedChannels.includes('Reddit')) specs.push({channel:'Reddit',platform:'Reddit',outputType:'Discussion Draft',scope:'one long-form draft'});
if(requestedChannels.includes('X / Twitter')) specs.push(
  {channel:'X / Twitter',platform:'X',outputType:'Value Post',scope:'one strong standalone post'},
  {channel:'X / Twitter',platform:'X',outputType:'Thread',scope:'one concise thread'}
);
if(requestedChannels.includes('LinkedIn')) specs.push({channel:'LinkedIn',platform:'LinkedIn',outputType:'Value Post',scope:'one concise professional post'});
if(requestedChannels.includes('Blog')) specs.push({channel:'Blog',platform:'Framer',outputType:'Framer Blog',scope:'one long-form blog'});
if(requestedChannels.includes('Resource')) specs.push({channel:'Resource',platform:'Framer',outputType:'Resource',scope:'one downloadable resource outline'});
if(requestedChannels.includes('Newsletter')) specs.push({channel:'Newsletter',platform:'Newsletter',outputType:contentChannel==='Alex Woung'?'Dulcy Newsletter':'Client Newsletter',scope:'one newsletter'});
if(!specs.length) throw new Error('None of the selected Distribution Channels have a configured output mapping.');

const context={parentRecordId:parent.id,contentChannel,title:String(f['YouTube Title']??'').trim()||String(f.Title??parent.id),description,script,youtubeUrl,videoUrl,transcript,clips,requestedChannels,specs,minimumScore,requestedCount};
const prompt=`You are Dulcy's content distribution editor. Generate only the outputs listed in OUTPUT SPECS. Do not create any unselected platform or output type. Return valid JSON only with one top-level key named drafts containing a non-empty array.

For clip-scoped outputs, create the requested platform row for each supplied clip and preserve that clip's recordId and media URL. For long-form outputs, use an empty clipRecordId. Every draft object must contain exactly: clipRecordId, platform, outputType, title, body, mediaUrl. Platform and outputType must exactly match OUTPUT SPECS. Use the actual video transcript and the actual selected clip transcripts as factual authority. Title, description, script and existing captions are secondary labels or drafts, never independent evidence for metrics, results, quotes, promises, or facts. Resolve any disagreement in favor of the actual transcripts. If a title contains a metric absent from the transcripts, do not repeat it. Clip-scoped posts must accurately describe that specific clip, not another clip or a broader unsupported parent claim. Use only evidence in the supplied context. Do not invent results, quotes, statistics, links, assets, giveaways, or client facts. Do not include markdown fences.

X / TWITTER VOICE AND SOP:
- Write as Alexander Woung (@alexwoung), not as a generic brand or content marketer.
- The purpose of X is fast ideas + a different angle + proof: sharpen thinking, test hooks, find winning angles, and turn winners into larger content.
- Match Alexander's observed voice: blunt, direct, compact, conversational, confident, occasionally lowercase, and willing to make a sharp comparison. It should sound typed by a founder, not polished by a corporate copywriter.
- Strong examples of the voice are: a clear contrast, an earned opinion, a specific bottleneck, a short reaction to proof, or a direct question.
- Never write generic tip-list filler, motivational-speaker language, engagement bait, fake controversy, AI-sounding transitions, hashtags, or unnecessary emojis.
- Do not over-explain. The first line must work alone, and the post must be interesting by line 3.
- Standalone Value Posts should normally fit within 280 characters. Prefer one strong idea over multiple weak ideas.
- Create one strong Value Post: choose a sharp opinion, specific earned lesson, proof/reaction, one-liner/pulse check, or compact story angle only as supported by the actual transcripts.
- A proof/case-study post may use a metric or result only when it appears in CONTENT CONTEXT. Format it as receipt + brief reaction + takeaway.
- Use a personal story only when the source contains a real situation, tension, and lesson. Keep the ending clean.
- Use a giveaway format only when CONTENT CONTEXT contains a real asset that can actually be delivered. Never invent a giveaway.
- A Thread should contain 3-6 short posts, each useful on its own, clearly separated with numbered labels such as "1/" and "2/". Do not stretch a single idea into filler.
- Titles are internal review labels, not text to publish. Keep each title short and descriptive.
- The operating cadence is 3-5 solid posts per week, Monday-Friday. Consistency and value matter more than trying to force one viral moment.
- Across an ongoing content mix, favor proof/case studies when supported, then personal stories, with occasional value posts, one-liners, or genuine giveaways. For this individual source, choose only formats supported by its evidence.

LINKEDIN VOICE AND SOP:
- Write as Alexander Woung for a professional audience that may be validating him after finding him through cold email, X, YouTube, Instagram, a referral, or search. LinkedIn is part of the trust funnel.
- LinkedIn is not X. Keep the post short, clean, straightforward, lead-focused, and credible. The goal is not to be the funniest person; it is to be the person the reader trusts.
- Every post must deliver real value and clarity. Use one point, one stance, and one clear takeaway. Do not turn a post into a blog or a generic list of 12 tips.
- Choose only one of three formats supported by CONTENT CONTEXT:
  1. Giveaway: a pain- or curiosity-led hook, three specific value bullets, real proof if available, and a CTA to comment a word and connect. Use this only when a genuinely valuable asset exists and can actually be delivered. Never invent an asset or recycled PDF.
  2. Story: a real moment, mistake or tension, lesson, and clean takeaway. A CTA is optional. Write it like a lesson, not a journal entry.
  3. Value post: teach one specific lesson with a clear stance and practical takeaway. Favor topics such as offer positioning, outreach bottlenecks, specific mistakes, or useful frameworks when supported by the source.
- The first two lines must establish the pain, curiosity, tension, or contrarian stance. Avoid vague openings, corporate throat-clearing, and AI-sounding transitions.
- Use short paragraphs with whitespace. Keep bullets tactical and specific. Do not use hashtags, fake vulnerability, invented dialogue, unsupported proof, or engagement bait.
- When CONTENT CONTEXT includes a clip or relevant media URL, preserve it in mediaUrl. Media should feel real: a video, personal photo, result screenshot, or simple one-idea graphic—not a generic template.
- Rough ongoing mix: about 75% of LinkedIn posts should use relevant media and 25% may be text-only. Do not invent a media URL when none is supplied.
- Titles are internal review labels, not copy to publish. Keep them short and descriptive.

OUTPUT SPECS:
${JSON.stringify(specs)}

CONTENT CONTEXT:
${JSON.stringify(context)}`;
return [{json:{parentRecordId:parent.id,contentChannel,context,prompt,requestedChannels,specs,managedSources:verifiedSources.filter(x=>clips.some(c=>c.recordId===x.recordId))}}];

